<div class="page-heading"><div><p class="eyebrow">Phase 5</p><h1>Operational Reports</h1></div><button class="btn btn-outline-secondary" onclick="window.print()"><i class="bi bi-printer me-2"></i>Print</button></div>
<div class="row g-4">
<div class="col-lg-6"><section class="panel"><h2 class="h5">Fee Balances</h2><table class="table"><thead><tr><th>Status</th><th>Invoices</th><th>Balance</th></tr></thead><tbody><?php foreach ($summary['fees'] as $row): ?><tr><td><?= e($row['status']) ?></td><td><?= e($row['count']) ?></td><td>KES <?= e(number_format((float)$row['balance'], 2)) ?></td></tr><?php endforeach; ?></tbody></table></section></div>
<div class="col-lg-6"><section class="panel"><h2 class="h5">Attendance Summary</h2><table class="table"><thead><tr><th>Status</th><th>Records</th></tr></thead><tbody><?php foreach ($summary['attendance'] as $row): ?><tr><td><?= e(ucfirst($row['status'])) ?></td><td><?= e($row['count']) ?></td></tr><?php endforeach; ?></tbody></table></section></div>
<div class="col-lg-6"><section class="panel"><h2 class="h5">Exam Performance</h2><table class="table"><thead><tr><th>Exam</th><th>Mean</th><th>Entries</th></tr></thead><tbody><?php foreach ($summary['exams'] as $row): ?><tr><td><?= e($row['name']) ?></td><td><?= e($row['mean_mark'] ?? 'N/A') ?></td><td><?= e($row['entries']) ?></td></tr><?php endforeach; ?></tbody></table></section></div>
<div class="col-lg-6"><section class="panel"><h2 class="h5">Low Stock</h2><table class="table"><thead><tr><th>Item</th><th>On Hand</th><th>Reorder At</th></tr></thead><tbody><?php foreach ($summary['stock'] as $row): ?><tr><td><?= e($row['item_code'] . ' · ' . $row['name']) ?></td><td><?= e($row['quantity_on_hand']) ?></td><td><?= e($row['reorder_level']) ?></td></tr><?php endforeach; ?></tbody></table></section></div>
</div>
